import { STORM_EVENTS_SNAPSHOT } from '../../src/layers/disasterHistory/stormEventsSnapshot.js';
import { OPENFEMA_URL } from '../../src/layers/disasterHistory/policy.js';
import { readResponseJsonCapped } from './common/http.js';

/**
 * County disaster-history proxy: OpenFEMA declarations (live) + the
 * static NOAA NCEI Storm Events snapshot (in-repo, generated by
 * scripts/generate-storm-events-snapshot.mjs).
 *
 * Upstream (OpenFEMA API v2, keyless, public domain):
 *   GET https://www.fema.gov/api/open/v2/DisasterDeclarationsSummaries
 *     ?$filter=state eq 'NJ' and designatedArea eq 'Cape May (County)'
 *     &$top=100&$orderby=declarationDate desc
 *
 * Verified live 2026-11-16: 34 declarations, 1965-08-18 (DR-205-NJ,
 * Drought, WATER SHORTAGE) → 2021-09-05 (DR-4614-NJ, Hurricane,
 * REMNANTS OF HURRICANE IDA). By type: Hurricane 10, Snowstorm 6,
 * Severe Storm 5, Flood 4, Biological 2, Drought 2, Coastal Storm 2,
 * Fire 1, Other 1, Severe Ice Storm 1. DR 22, EM 12.
 *
 * Storm Events has no query API — NCEI's access API rejects
 * dataset=stormevents ("Unsupported dataset", verified 2026-11-16) — so
 * its half is a curated snapshot, not a runtime download: one year's
 * details file is ~12 MB gzipped. The snapshot (years 2012/2021/2024/
 * 2025, 145 rows) is served as-is with its source filenames.
 *
 * Cadence: declarations change rarely — the proxy caches 24 hours; the
 * layer polls once a day. On upstream failure serve the stale cache with
 * its fetch time; a cold cache answers 502.
 *
 * Routes:
 *   GET /api/disaster-history        → {fetchedAt, stale, ttlMs, fema, stormEvents}
 *   GET /api/disaster-history/status → {lastFetch, stale, ttlMs, declarationCount, stormEventYears}
 *
 * @returns {import('vite').Plugin}
 */

export const DISASTER_HISTORY_PROXY_TTL_MS = 24 * 60 * 60_000;
export const DISASTER_HISTORY_PROXY_TIMEOUT_MS = 15_000;
export const DISASTER_HISTORY_PROXY_USER_AGENT =
  'gods-eye-view/1.0 (+https://capemaydispatch.com)';
const DISASTER_HISTORY_MAX_RESPONSE_BYTES = 1024 * 1024;
const DISASTER_HISTORY_BACKOFF_MS = 60_000;

function declarationCount(entry) {
  const rows = entry?.fema?.DisasterDeclarationsSummaries;
  return Array.isArray(rows) ? rows.length : null;
}

export function disasterHistoryProxy({
  fetchImpl = (...args) => globalThis.fetch(...args),
  now = () => Date.now(),
  warn = (...args) => console.warn(...args),
} = {}) {
  /** @type {?{at: number, fema: object}} */
  let mem = null;
  /** @type {?Promise<?object>} single-flight refresh */
  let inflight = null;
  let backoffUntil = 0;
  let lastFailure = null;

  async function fetchUpstreamJson(signal) {
    const res = await fetchImpl(OPENFEMA_URL, {
      signal,
      headers: {
        Accept: 'application/json',
        'User-Agent': DISASTER_HISTORY_PROXY_USER_AGENT,
      },
    });
    if (!res.ok) {
      await res.body?.cancel().catch(() => {});
      throw new Error(`HTTP ${res.status}`);
    }
    const payload = await readResponseJsonCapped(
      res,
      DISASTER_HISTORY_MAX_RESPONSE_BYTES,
      signal,
    );
    if (!payload || typeof payload !== 'object' || Array.isArray(payload))
      throw new Error('non-JSON upstream response');
    if (!Array.isArray(payload.DisasterDeclarationsSummaries))
      throw new Error('OpenFEMA response missing declarations');
    return payload;
  }

  function buildPayload(entry, stale) {
    return {
      fetchedAt: entry.at,
      stale,
      ttlMs: DISASTER_HISTORY_PROXY_TTL_MS,
      fema: entry.fema,
      stormEvents: {
        source: STORM_EVENTS_SNAPSHOT.source,
        sourceFiles: STORM_EVENTS_SNAPSHOT.sourceFiles,
        generated: STORM_EVENTS_SNAPSHOT.generated,
        years: STORM_EVENTS_SNAPSHOT.years,
      },
    };
  }

  const installMiddleware = (server) => {
    server.middlewares.use('/api/disaster-history', async (req, res) => {
      const sendJson = (status, obj) => {
        if (res.headersSent) return;
        res.writeHead(status, {
          'Content-Type': 'application/json',
          'Cache-Control': 'no-store',
        });
        res.end(JSON.stringify(obj));
      };
      try {
        const subPath = String(req.url || '').split('?')[0];

        if (subPath === '/status') {
          sendJson(200, {
            lastFetch: mem ? mem.at : null,
            stale: mem
              ? now() - mem.at >= DISASTER_HISTORY_PROXY_TTL_MS
              : false,
            ttlMs: DISASTER_HISTORY_PROXY_TTL_MS,
            declarationCount: mem ? declarationCount(mem) : null,
            stormEventYears: Object.keys(STORM_EVENTS_SNAPSHOT.years).sort(),
          });
          return;
        }

        const entry = mem;
        if (entry && now() - entry.at < DISASTER_HISTORY_PROXY_TTL_MS) {
          sendJson(200, buildPayload(entry, false));
          return;
        }
        if (now() < backoffUntil) {
          if (entry) {
            sendJson(200, buildPayload(entry, true));
            return;
          }
          sendJson(502, {
            error:
              lastFailure ?? 'OpenFEMA fetch failed and no cache available',
          });
          return;
        }
        if (!inflight) {
          const signal = AbortSignal.timeout(DISASTER_HISTORY_PROXY_TIMEOUT_MS);
          inflight = fetchUpstreamJson(signal)
            .then((fema) => {
              mem = { at: now(), fema };
              backoffUntil = 0;
              lastFailure = null;
              return mem;
            })
            .catch((err) => {
              backoffUntil = now() + DISASTER_HISTORY_BACKOFF_MS;
              lastFailure = null;
              warn(
                `[disaster-history-proxy] refresh failed (${err?.message || err}) — serving cache if any`,
              );
              return null;
            })
            .finally(() => {
              inflight = null;
            });
        }
        const pending = inflight;
        const fresh = await pending;
        if (fresh) {
          sendJson(200, buildPayload(fresh, false));
        } else if (entry) {
          sendJson(200, buildPayload(entry, true)); // upstream down — stale beats empty
        } else {
          sendJson(502, {
            error:
              lastFailure ?? 'OpenFEMA fetch failed and no cache available',
          });
        }
      } catch (err) {
        warn('[disaster-history-proxy] error:', err?.message || err);
        sendJson(500, { error: 'disaster history proxy error' });
      }
    });
  };
  return {
    name: 'disaster-history-proxy',
    configureServer: installMiddleware,
    configurePreviewServer: installMiddleware,
  };
}
